using System.Windows; using System.Windows.Controls; using AutoPecasERP.Data.Context; using AutoPecasERP.Core.Entities; using Microsoft.EntityFrameworkCore;
namespace AutoPecasERP.Desktop.Views; public partial class ClientesWindow:Window { public ClientesWindow(){InitializeComponent();Carregar();} async void Carregar(string q=""){using var db=new ErpDbContext();GridDados.ItemsSource=await db.Clientes.Where(x=>q==""||x.Nome.Contains(q)||(x.CpfCnpj??"").Contains(q)).OrderBy(x=>x.Nome).ToListAsync();} void Busca_TextChanged(object s,TextChangedEventArgs e)=>Carregar(Busca.Text.Trim()); async void Novo_Click(object s,RoutedEventArgs e){var w=new ClienteEditWindow(){Owner=this};if(w.ShowDialog()==true)Carregar();} async void Excluir_Click(object s,RoutedEventArgs e){if(GridDados.SelectedItem is Cliente c && MessageBox.Show($"Excluir {c.Nome}?","Confirmação",MessageBoxButton.YesNo)==MessageBoxResult.Yes){using var db=new ErpDbContext();db.Clientes.Remove(c);await db.SaveChangesAsync();Carregar();}} void Atualizar_Click(object s,RoutedEventArgs e)=>Carregar(Busca.Text.Trim()); }